 dict(id='S3',case='C07',change='Motivation exclusivement commerciale → motivation mixte comportant un engagement moral effectif.',before='L’origine morale est contredite par la stipulation d’exclusivité.',after='La réfutation automatique disparaît ; il faut établir le rôle de l’engagement dans l’action.',lesson='Profits et engagement moral ne sont pas logiquement incompatibles.',sources=['DCJ:422–423']),
